function deepClone(value, seen = new WeakMap()) {
  if (value === null || typeof value !== 'object') return value;  // primitives copy by value
  if (seen.has(value)) return seen.get(value);                    // cycle: return prior clone
  const out = Array.isArray(value) ? [] : {};
  seen.set(value, out);                                           // register BEFORE recursing
  for (const k of Object.keys(value)) out[k] = deepClone(value[k], seen);
  return out;
}

